INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5296664, 771645, 87751, '<td valign="top">I like it!!</td>', 'I like it!!', '2009-03-09 00:02:55.000000', NULL, 1),
(5296683, 770891, 54645, '<td valign="top">funky editing, great subject, natural choice.</td>', 'funky editing, great subject, natural choice.', '2009-03-09 00:09:13.000000', NULL, 1),
(5296684, 770897, 54645, '<td valign="top">Fantastic color.</td>', 'Fantastic color.', '2009-03-09 00:09:46.000000', NULL, 1),
(5296685, 771609, 83313, '<td valign="top">Nice old timey feel to this. I want to kick up my feet and sit a spell.</td>', 'Nice old timey feel to this. I want to kick up my feet and sit a spell.', '2009-03-09 00:09:46.000000', NULL, 1),
(5296693, 770926, 83313, '<td valign="top">Doesn''t look older than perhaps the 60''s, but it looks like maybe the building in the rear is older than the lower one in the foreground. Nice sunset glow in the windows and a gorgeous blue sky.</td>', 'Doesn''t look older than perhaps the 60''s, but it looks like maybe the building in the rear is older than the lower one in the foreground. Nice sunset glow in the windows and a gorgeous blue sky.', '2009-03-09 00:11:29.000000', NULL, 1),
(5296697, 771184, 83313, '<td valign="top">A bit too centered and soft for my own preference. I think there is lots of great contrasty detail here, however.</td>', 'A bit too centered and soft for my own preference. I think there is lots of great contrasty detail here, however.', '2009-03-09 00:12:26.000000', NULL, 1),
(5296700, 771593, 30861, '<td valign="top">Oh, blast from the past for me! Brown University, 1968 here. Nice shot.</td>', 'Oh, blast from the past for me! Brown University, 1968 here. Nice shot.', '2009-03-09 00:13:01.000000', NULL, 1),
(5296701, 771651, 83313, '<td valign="top">A 100+ year old dried flower? I''ll bet you had to handle it carefully!</td>', 'A 100+ year old dried flower? I''ll bet you had to handle it carefully!', '2009-03-09 00:13:08.000000', NULL, 1),
(5296705, 771589, 100301, '<td valign="top">cool picture.  Although, isn''t that a 1920''s model?  I think the older ones looked alot more like a "horseless carriage".</td>', 'cool picture.  Although, isn''t that a 1920''s model?  I think the older ones looked alot more like a "horseless carriage".', '2009-03-09 00:13:46.000000', NULL, 1),
(5296707, 771533, 13390, '<td valign="top">Great sky and I really like the tonal depth with your BW editing.</td>', 'Great sky and I really like the tonal depth with your BW editing.', '2009-03-09 00:14:05.000000', NULL, 1),
(5296716, 771308, 83313, '<td valign="top">I''m afraid this comes off to me as a good snapshot. Mostly, I think you may have been using your camera''s built in flash, which tends to be really harsh and unflattering for most subjects. A 96k file size also indicates you could have used less compression and maybe gotten some more clarity in this.</td>', 'I''m afraid this comes off to me as a good snapshot. Mostly, I think you may have been using your camera''s built in flash, which tends to be really harsh and unflattering for most subjects. A 96k file size also indicates you could have used less compression and maybe gotten some more clarity in this.', '2009-03-09 00:16:04.000000', NULL, 1),
(5296717, 771082, 100301, '<td valign="top">in other news, there are castles in kansas...  I guess this was a low light situation, not as sharp as I''d like it to be, but an interesting find never-the-less.</td>', 'in other news, there are castles in kansas...  I guess this was a low light situation, not as sharp as I''d like it to be, but an interesting find never-the-less.', '2009-03-09 00:16:13.000000', NULL, 1),
(5296718, 771355, 83313, '<td valign="top">I like the processing on this. It really does justice to the old tower.</td>', 'I like the processing on this. It really does justice to the old tower.', '2009-03-09 00:16:41.000000', NULL, 1),
(5296724, 771516, 54645, '<td valign="top">Great stuff! I''ve been here many times.</td>', 'Great stuff! I''ve been here many times.', '2009-03-09 00:18:21.000000', NULL, 1),
(5296731, 771039, 100301, '<td valign="top">interesting take on an oft captured photographic subject.  love the composition, the gull, and the tone.  Maybe would have cloned out the boat if I was going to put it on my wall, but that''s just me.</td>', 'interesting take on an oft captured photographic subject.  love the composition, the gull, and the tone.  Maybe would have cloned out the boat if I was going to put it on my wall, but that''s just me.', '2009-03-09 00:19:05.000000', NULL, 1),
(5296739, 771466, 54645, '<td valign="top">Looks like a splash scene from a computer game!</td>', 'Looks like a splash scene from a computer game!', '2009-03-09 00:21:29.000000', NULL, 1),
(5296743, 770869, 100301, '<td valign="top">I shudder to think of the tools a dentist in a building that old may have used... That aside, I can''t decide if I love or hate the fence.  It obviously communicates your title, but it''s such a cool building it''s unfortunate that it''s there at the same time.  All in all, great photo, 8</td>', 'I shudder to think of the tools a dentist in a building that old may have used... That aside, I can''t decide if I love or hate the fence.  It obviously communicates your title, but it''s such a cool building it''s unfortunate that it''s there at the same time.  All in all, great photo, 8', '2009-03-09 00:23:00.000000', NULL, 1),
(5296762, 771257, 100301, '<td valign="top">you can''t be serious...</td>', 'you can''t be serious...', '2009-03-09 00:29:46.000000', NULL, 1),
(5296768, 771538, 14476, '<td valign="top">The shadow makes this one stand out</td>', 'The shadow makes this one stand out', '2009-03-09 00:32:18.000000', NULL, 1),
(5296780, 770486, 50641, '<td valign="top">beautiful light!</td>', 'beautiful light!', '2009-03-09 00:36:59.000000', NULL, 1),
(5296785, 771624, 1717, '<td valign="top">i have no words grand enough to describe how fabulous this image is and it can only be the work of the nonpareil RKT...truly, the one photographer at DPC who makes me turn green with envy at her boundless talent.</td>', 'i have no words grand enough to describe how fabulous this image is and it can only be the work of the nonpareil RKT...truly, the one photographer at DPC who makes me turn green with envy at her boundless talent.', '2009-03-09 00:41:42.000000', NULL, 1),
(5296791, 770869, 69668, '<td valign="top">If it were not for that stinkin fence...I''d love this shot.  However, the fence adds a different element to the composition.  I do rather like the overall image; my preference would be without the fence, though. 7</td>', 'If it were not for that stinkin fence...I''d love this shot.  However, the fence adds a different element to the composition.  I do rather like the overall image; my preference would be without the fence, though. 7', '2009-03-09 00:45:06.000000', NULL, 1),
(5296793, 771547, 69668, '<td valign="top">How fun is this.  The clothing is terrific.  I love the setting, and the overall post processing really brings this back in time.  Well done. 7</td>', 'How fun is this.  The clothing is terrific.  I love the setting, and the overall post processing really brings this back in time.  Well done. 7', '2009-03-09 00:46:33.000000', NULL, 1),
(5296814, 771508, 39880, '<td valign="top">Lighting looks nice, but it''s just a bit blurry.</td>', 'Lighting looks nice, but it''s just a bit blurry.', '2009-03-09 01:02:52.000000', NULL, 1),
(5296838, 771342, 15407, '<td valign="top">That black piece is very distracting</td>', 'That black piece is very distracting', '2009-03-09 01:20:13.000000', NULL, 1),
(5296840, 771624, 15407, '<td valign="top">Picture of a pictur?</td>', 'Picture of a pictur?', '2009-03-09 01:20:53.000000', NULL, 1),
(5296843, 770696, 67237, '<td valign="top">lovely shot, I would have removed the Dorito''s empty bag from her side though :-)</td>', 'lovely shot, I would have removed the Dorito''s empty bag from her side though :-)', '2009-03-09 01:23:46.000000', NULL, 1),
(5296844, 771616, 98022, '<td valign="top">Great perspective and DOF. I like the B/W treatment.</td>', 'Great perspective and DOF. I like the B/W treatment.', '2009-03-09 01:23:54.000000', NULL, 1),
(5296855, 770897, 31637, '<td valign="top">Great colors and composition. Nice crop if you did so, 7</td>', 'Great colors and composition. Nice crop if you did so, 7', '2009-03-09 01:38:29.000000', NULL, 1),
(5296856, 770300, 31637, '<td valign="top">Nice exposure on palace, but the rest of the photo is too dark in this case.</td>', 'Nice exposure on palace, but the rest of the photo is too dark in this case.', '2009-03-09 01:39:28.000000', NULL, 1),
(5296860, 770486, 31637, '<td valign="top">Over-processed bridge, the rest of the photo is wonderful, filling the frame.</td>', 'Over-processed bridge, the rest of the photo is wonderful, filling the frame.', '2009-03-09 01:43:47.000000', NULL, 1),
(5296862, 770891, 31637, '<td valign="top">Definitely the Cro-Magnon''s first marvel, the sky looks too over the top for this, the henge needs some sunlight here!</td>', 'Definitely the Cro-Magnon''s first marvel, the sky looks too over the top for this, the henge needs some sunlight here!', '2009-03-09 01:46:06.000000', NULL, 1),
(5296869, 771474, 83313, '<td valign="top">This brings back some memories to me. When I was a little kid (60''s) I remember imagining my mom as a little girl (which was in the 40''s) and my grandmother sitting at a spinning wheel. I once asked my mother what things were like when she was a little girl, back in "the olden days". I clearly recall her jaw dropping, and she said: "I''m not THAT old!!". <br/> <br/>Interesting subject and I can see that you tried to get a good low perspective on it. I think the photo comes off a little soft, but not old looking, if that makes sense. The spinning wheel may be a little too centered in the frame and it is cut off at the top and bottom.</td>', 'This brings back some memories to me. When I was a little kid (60''s) I remember imagining my mom as a little girl (which was in the 40''s) and my grandmother sitting at a spinning wheel. I once asked my mother what things were like when she was a little girl, back in "the olden days". I clearly recall her jaw dropping, and she said: "I''m not THAT old!!".  Interesting subject and I can see that you tried to get a good low perspective on it. I think the photo comes off a little soft, but not old looking, if that makes sense. The spinning wheel may be a little too centered in the frame and it is cut off at the top and bottom.', '2009-03-09 01:59:01.000000', NULL, 1),
(5296870, 771430, 83313, '<td valign="top">Nice sharp details and good comp with a nice leading perspective. I like this.</td>', 'Nice sharp details and good comp with a nice leading perspective. I like this.', '2009-03-09 01:59:57.000000', NULL, 1),
(5296874, 770486, 69668, '<td valign="top">Very nice post processing...the light is well controlled and the processing take it to the edge but I think you did not take it over the top. 8</td>', 'Very nice post processing...the light is well controlled and the processing take it to the edge but I think you did not take it over the top. 8', '2009-03-09 02:10:00.000000', NULL, 1),
(5296875, 771651, 69668, '<td valign="top">That is really a 100 year old flower?  If is is I am impressed that it has made it through all these times.</td>', 'That is really a 100 year old flower?  If is is I am impressed that it has made it through all these times.', '2009-03-09 02:11:16.000000', NULL, 1),
(5296876, 771549, 69668, '<td valign="top">Nice soft exposure and light...or processing.</td>', 'Nice soft exposure and light...or processing.', '2009-03-09 02:11:46.000000', NULL, 1),
(5296877, 771399, 69668, '<td valign="top">I love that reflection.  How lucky were you to get to be there.</td>', 'I love that reflection.  How lucky were you to get to be there.', '2009-03-09 02:12:14.000000', NULL, 1),
(5296878, 770556, 69668, '<td valign="top">A symbol from over 100 years ago that still represents alot.  I like that you choose to photograph this subject.  I am not to crazy about the lens baby used.</td>', 'A symbol from over 100 years ago that still represents alot.  I like that you choose to photograph this subject.  I am not to crazy about the lens baby used.', '2009-03-09 02:13:18.000000', NULL, 1),
(5296879, 770638, 69668, '<td valign="top">I like the sky color reflected in the windows.  Seems a tad over-saturated on the reds.  Overall nice subject. 6</td>', 'I like the sky color reflected in the windows.  Seems a tad over-saturated on the reds.  Overall nice subject. 6', '2009-03-09 02:14:02.000000', NULL, 1),
(5296884, 770608, 76430, '<td valign="top">I love this view from near the beach.  I didn''t realize the Hotel Del was that old.  I think some more saturation would be good here, bringing out the green in the grass and really emphasizing the red roof, and maybe bringing out some blue through the cloud layer..</td>', 'I love this view from near the beach.  I didn''t realize the Hotel Del was that old.  I think some more saturation would be good here, bringing out the green in the grass and really emphasizing the red roof, and maybe bringing out some blue through the cloud layer..', '2009-03-09 02:40:21.000000', NULL, 1),
(5296887, 771609, 100646, '<td valign="top">The borders draw my eyes away from the picture to much. otherwise I like this image a lot.</td>', 'The borders draw my eyes away from the picture to much. otherwise I like this image a lot.', '2009-03-09 02:52:38.000000', NULL, 1),
(5296889, 771566, 100646, '<td valign="top">to much editing imo.</td>', 'to much editing imo.', '2009-03-09 02:54:51.000000', NULL, 1),
(5296891, 771601, 100646, '<td valign="top">I dont understand why this picture was edited this way. I''d have to see the original to make a fair vote I think.</td>', 'I dont understand why this picture was edited this way. I''d have to see the original to make a fair vote I think.', '2009-03-09 02:56:09.000000', NULL, 1),
(5296910, 771404, 15407, '<td valign="top">That thing must have been living on ACID!</td>', 'That thing must have been living on ACID!', '2009-03-09 03:23:08.000000', NULL, 1),
(5296930, 770671, 15407, '<td valign="top">I''ve felt like this before... Why Me?</td>', 'I''ve felt like this before... Why Me?', '2009-03-09 03:57:03.000000', NULL, 1),
(5296954, 770538, 73873, '<td valign="top">I think a slightly higher point of view so that the building was not obscured by the fence would have made a huge difference and would add depth and perspective to this shot.</td>', 'I think a slightly higher point of view so that the building was not obscured by the fence would have made a huge difference and would add depth and perspective to this shot.', '2009-03-09 04:54:56.000000', NULL, 1),
(5296956, 771601, 73873, '<td valign="top">This would look much better with perspective correction</td>', 'This would look much better with perspective correction', '2009-03-09 04:55:40.000000', NULL, 1),
(5296958, 771148, 73873, '<td valign="top">This pic would benefit from greater depth of field or a faster shutter speed as the area around the waterfall is not sharp.</td>', 'This pic would benefit from greater depth of field or a faster shutter speed as the area around the waterfall is not sharp.', '2009-03-09 04:56:59.000000', NULL, 1),
(5296959, 771436, 73873, '<td valign="top">Interesting...but a lower angle would lead the eye along the rails more, pulling the viewer into the photo</td>', 'Interesting...but a lower angle would lead the eye along the rails more, pulling the viewer into the photo', '2009-03-09 04:57:53.000000', NULL, 1),
(5296960, 769958, 73873, '<td valign="top">Nice postcard look. Perhaps you could clone out the power lines as this is an advanced editing challenge</td>', 'Nice postcard look. Perhaps you could clone out the power lines as this is an advanced editing challenge', '2009-03-09 04:58:41.000000', NULL, 1),
(5296962, 770642, 73873, '<td valign="top">Interesting but too fuzzy</td>', 'Interesting but too fuzzy', '2009-03-09 04:59:32.000000', NULL, 1),
(5296965, 771323, 73873, '<td valign="top">Very dramatic, but I think it would look better with perspective correction</td>', 'Very dramatic, but I think it would look better with perspective correction', '2009-03-09 05:00:42.000000', NULL, 1),
(5296969, 769959, 73873, '<td valign="top">Nice idea, very sharp which is good, but perhaps moving the doll into the left half of the frame and giving it some room on the right side would be interesting</td>', 'Nice idea, very sharp which is good, but perhaps moving the doll into the left half of the frame and giving it some room on the right side would be interesting', '2009-03-09 05:02:22.000000', NULL, 1),
(5296971, 771602, 73873, '<td valign="top">Lovely</td>', 'Lovely', '2009-03-09 05:02:44.000000', NULL, 1),
(5296972, 770897, 73873, '<td valign="top">Very interesting, lovely colours, sharp, but perhaps if the cupola was on the top 1/3 of the frame it would be more compelling and draw the viewer into the photo</td>', 'Very interesting, lovely colours, sharp, but perhaps if the cupola was on the top 1/3 of the frame it would be more compelling and draw the viewer into the photo', '2009-03-09 05:05:04.000000', NULL, 1),
(5296975, 770560, 73873, '<td valign="top">I like this a lot. Would it be more compelling if you could also see the script on the headstones?</td>', 'I like this a lot. Would it be more compelling if you could also see the script on the headstones?', '2009-03-09 05:06:42.000000', NULL, 1),
(5296977, 770854, 73873, '<td valign="top">Wow...very impressive</td>', 'Wow...very impressive', '2009-03-09 05:07:31.000000', NULL, 1),
(5297005, 771399, 85148, '<td valign="top">great photo!!!</td>', 'great photo!!!', '2009-03-09 05:40:28.000000', NULL, 1),
(5297006, 771516, 85148, '<td valign="top">wow....what a dildo!</td>', 'wow....what a dildo!', '2009-03-09 05:40:52.000000', NULL, 1),
(5297007, 771515, 85148, '<td valign="top">spooky</td>', 'spooky', '2009-03-09 05:40:58.000000', NULL, 1),
(5297008, 771227, 85148, '<td valign="top">tree is too close</td>', 'tree is too close', '2009-03-09 05:41:21.000000', NULL, 1),
(5297043, 771593, 104116, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2009-03-09 06:28:38.000000', NULL, 1),
(5297047, 771547, 104116, '<td valign="top">Great capture - I really like the vintage style!</td>', 'Great capture - I really like the vintage style!', '2009-03-09 06:37:07.000000', NULL, 1),
(5297049, 771392, 51538, '<td valign="top">If you have to use the title to explain why the image is entered in the challenge, it is not much of an entry.</td>', 'If you have to use the title to explain why the image is entered in the challenge, it is not much of an entry.', '2009-03-09 06:38:44.000000', NULL, 1),
(5297052, 769987, 104116, '<td valign="top">This place is a beauty, haunting image.  Nice job.</td>', 'This place is a beauty, haunting image.  Nice job.', '2009-03-09 06:39:59.000000', NULL, 1),
(5297078, 771111, 99263, '<td valign="top">Excellent composition with remarkable detail. Beautiful capture of flowing water motion. 9</td>', 'Excellent composition with remarkable detail. Beautiful capture of flowing water motion. 9', '2009-03-09 07:16:05.000000', NULL, 1),
(5297097, 770538, 99218, '<td valign="top">nice shot!</td>', 'nice shot!', '2009-03-09 08:05:13.000000', NULL, 1),
(5297098, 771149, 99218, '<td valign="top">nice shot!</td>', 'nice shot!', '2009-03-09 08:05:17.000000', NULL, 1),
(5297099, 771213, 99218, '<td valign="top">awsome shot!</td>', 'awsome shot!', '2009-03-09 08:07:26.000000', NULL, 1),
(5297103, 771233, 99218, '<td valign="top">amazing....nice shot!</td>', 'amazing....nice shot!', '2009-03-09 08:10:58.000000', NULL, 1),
