(5297278, 770684, 99263, '<td valign="top">Great angle you took this shot from emphasizing the dramatic architecture of this castle. Pity about the bland sky but I know from experience that those skies are typical in the UK at this time of year and one can''t do much about it.</td>', 'Great angle you took this shot from emphasizing the dramatic architecture of this castle. Pity about the bland sky but I know from experience that those skies are typical in the UK at this time of year and one can''t do much about it.', '2009-03-09 09:58:17.000000', NULL, 1),
(5297279, 770300, 99263, '<td valign="top">Dramatic night shot of Westminster.</td>', 'Dramatic night shot of Westminster.', '2009-03-09 09:58:21.000000', NULL, 1),
(5297280, 770696, 102811, '<td valign="top">I think your ambition with this image is to be commended although the resulting image is a little wanting in some areas. The blue and red ''thing'' is the biggest distraction. Good effort to be different.</td>', 'I think your ambition with this image is to be commended although the resulting image is a little wanting in some areas. The blue and red ''thing'' is the biggest distraction. Good effort to be different.', '2009-03-09 09:58:27.000000', NULL, 1),
(5297289, 771609, 99263, '<td valign="top">Beautiful light, beautiful scene. Wonderful atmosphere. Lovely painting like effect. 10</td>', 'Beautiful light, beautiful scene. Wonderful atmosphere. Lovely painting like effect. 10', '2009-03-09 10:01:53.000000', NULL, 1),
(5297290, 770900, 99263, '<td valign="top">Beautiful processing. Lovely colors and clarity with superb detail. Eye catching image with great composition. 9</td>', 'Beautiful processing. Lovely colors and clarity with superb detail. Eye catching image with great composition. 9', '2009-03-09 10:02:09.000000', NULL, 1),
(5297291, 771229, 99263, '<td valign="top">Very nicely captured street scene. I like the angle you chose and how the wet, glistening cobblestone street fills most of the frame and leads the eyes into the scene. 8</td>', 'Very nicely captured street scene. I like the angle you chose and how the wet, glistening cobblestone street fills most of the frame and leads the eyes into the scene. 8', '2009-03-09 10:02:15.000000', NULL, 1),
