(5298335, 771508, 34058, '<td valign="top">Beautiful clock, just a little out of focus, maybe try using a tripod next time to get a really clear shot</td>', 'Beautiful clock, just a little out of focus, maybe try using a tripod next time to get a really clear shot', '2009-03-09 21:34:03.000000', NULL, 1),
(5298337, 771257, 34058, '<td valign="top">What an old kitty!  I like the look on his face, but the white blanket is distracting.</td>', 'What an old kitty!  I like the look on his face, but the white blanket is distracting.', '2009-03-09 21:34:56.000000', NULL, 1),
