(5298341, 769857, 34058, '<td valign="top">I know you meant to do the lighting that way, but I just don''t think it really does the picture any justice.  I would have liked to see more of the clock.</td>', 'I know you meant to do the lighting that way, but I just don''t think it really does the picture any justice.  I would have liked to see more of the clock.', '2009-03-09 21:36:26.000000', NULL, 1),
(5298345, 770854, 98771, '<td valign="top">Has a magical feel to it, nice work.</td>', 'Has a magical feel to it, nice work.', '2009-03-09 21:37:36.000000', NULL, 1),
(5298346, 770608, 34058, '<td valign="top">Pretty hotel, just something about the colors in this could have been better.  I also think the tree in the foreground isn''t needed to make the picture.</td>', 'Pretty hotel, just something about the colors in this could have been better.  I also think the tree in the foreground isn''t needed to make the picture.', '2009-03-09 21:37:43.000000', NULL, 1),
(5298349, 771438, 23317, '<td valign="top">The bubble effect of the shot didn''t come through for me.  Love the contrast of the house with the sky.</td>', 'The bubble effect of the shot didn''t come through for me.  Love the contrast of the house with the sky.', '2009-03-09 21:39:02.000000', NULL, 1),
(5298350, 771046, 98771, '<td valign="top">Nice piece of history, what a treasure. Nice job.</td>', 'Nice piece of history, what a treasure. Nice job.', '2009-03-09 21:39:06.000000', NULL, 1),
(5298351, 770867, 34058, '<td valign="top">I like the border on this but the picture, to me, is just a little oof.</td>', 'I like the border on this but the picture, to me, is just a little oof.', '2009-03-09 21:39:43.000000', NULL, 1),
(5298355, 771474, 34058, '<td valign="top">I like the grainy effect on this, but looses it''s clairity towards the top and just a little to close of a crop on top too.</td>', 'I like the grainy effect on this, but looses it''s clairity towards the top and just a little to close of a crop on top too.', '2009-03-09 21:41:00.000000', NULL, 1);
