(5298682, 771518, 96751, '<td valign="top">Great macro.  Love the tones, the beaten up surface, the details.  The reflection also enhances the shot.  Great work.</td>', 'Great macro.  Love the tones, the beaten up surface, the details.  The reflection also enhances the shot.  Great work.', '2009-03-10 02:38:01.000000', NULL, 1),
(5298683, 771233, 96751, '<td valign="top">Except for the tilt, this is a stunning shot.  The rosette lights are beautiful against the columns.  Nice texture in the seats and the ceiling.</td>', 'Except for the tilt, this is a stunning shot.  The rosette lights are beautiful against the columns.  Nice texture in the seats and the ceiling.', '2009-03-10 02:38:54.000000', NULL, 1),
