(5298737, 771652, 99506, '<td valign="top">I really like the use of the subtle title.<br/> <br/>Very nice positioning of the scissors such that they dont obscure the woodcut print.<br/> <br/>Good work 9</td>', 'I really like the use of the subtle title. Very nice positioning of the scissors such that they dont obscure the woodcut print. Good work 9', '2009-03-10 04:52:24.000000', NULL, 1),
(5298738, 771163, 99506, '<td valign="top">That wood looks pretty good for 730 odd years old<br/>Nice shot</td>', 'That wood looks pretty good for 730 odd years oldNice shot', '2009-03-10 04:54:15.000000', NULL, 1),
