(5299732, 770992, 104116, '<td valign="top">I quite like the blackness of the sky and what it might say about this image.</td>', 'I quite like the blackness of the sky and what it might say about this image.', '2009-03-10 19:53:39.000000', NULL, 1),
(5299734, 771111, 104116, '<td valign="top">Nice image overall, power lines are a bit distracting from  the rest of the image.</td>', 'Nice image overall, power lines are a bit distracting from  the rest of the image.', '2009-03-10 19:55:01.000000', NULL, 1),
(5299736, 771602, 104116, '<td valign="top">Nice capture this proves to be an interesting compostion.</td>', 'Nice capture this proves to be an interesting compostion.', '2009-03-10 19:55:55.000000', NULL, 1),
