(5299770, 771626, 20748, '<td valign="top">the perspective of this throws me off a bit. the building looks pretty much parallel all the way up but you have other buildings creeping in the corners.</td>', 'the perspective of this throws me off a bit. the building looks pretty much parallel all the way up but you have other buildings creeping in the corners.', '2009-03-10 20:18:42.000000', NULL, 1),
(5299772, 771637, 98771, '<td valign="top">Beautiful, you''ve done well.</td>', 'Beautiful, you''ve done well.', '2009-03-10 20:19:46.000000', NULL, 1),
(5299777, 771566, 20748, '<td valign="top">way too much editing.</td>', 'way too much editing.', '2009-03-10 20:21:05.000000', NULL, 1),
(5299781, 771430, 98771, '<td valign="top">Really like the tones in this, nice work.</td>', 'Really like the tones in this, nice work.', '2009-03-10 20:23:32.000000', NULL, 1),
(5299793, 770916, 20748, '<td valign="top">the three doesn''t look to be over 100 year old.</td>', 'the three doesn''t look to be over 100 year old.', '2009-03-10 20:37:29.000000', NULL, 1),
(5299796, 771185, 20748, '<td valign="top">This is just my opinion, any tree over 100 years needs to be at least 14 inches thick.</td>', 'This is just my opinion, any tree over 100 years needs to be at least 14 inches thick.', '2009-03-10 20:40:52.000000', NULL, 1),
