INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5299882, 771602, 102315, '<td valign="top">Is this for the Eagles songs challenge? Just kidding. I like the details in this photo. Very sharp and crisp lines.</td>', 'Is this for the Eagles songs challenge? Just kidding. I like the details in this photo. Very sharp and crisp lines.', '2009-03-10 21:42:41.000000', NULL, 1),
(5299885, 771213, 102315, '<td valign="top">This photo looks similar to one that I put in my favorites already? NikonJeb? Again very nice photo. I love the style and the look of this. 10</td>', 'This photo looks similar to one that I put in my favorites already? NikonJeb? Again very nice photo. I love the style and the look of this. 10', '2009-03-10 21:45:00.000000', NULL, 1),
(5299897, 771163, 98771, '<td valign="top">She''s sharp, love the detail in the roof. Well done.</td>', 'She''s sharp, love the detail in the roof. Well done.', '2009-03-10 21:52:25.000000', NULL, 1),
(5299900, 770637, 98771, '<td valign="top">Really nice lighting, and nice color contrast. Well done.</td>', 'Really nice lighting, and nice color contrast. Well done.', '2009-03-10 21:53:45.000000', NULL, 1),
(5299908, 771289, 98771, '<td valign="top">Really like the composition of your shot, but it looks a little dark on my screen. Could just be my screen.</td>', 'Really like the composition of your shot, but it looks a little dark on my screen. Could just be my screen.', '2009-03-10 21:57:29.000000', NULL, 1),
(5299930, 771397, 53316, '<td valign="top">Wow, this place looks like it has a ton of character. I love it!</td>', 'Wow, this place looks like it has a ton of character. I love it!', '2009-03-10 22:06:22.000000', NULL, 1),
(5299932, 770854, 53316, '<td valign="top">What an amazing photo.... lovely colors and deep blacks create such a great mood - and that sky is just perfect.</td>', 'What an amazing photo.... lovely colors and deep blacks create such a great mood - and that sky is just perfect.', '2009-03-10 22:07:01.000000', NULL, 1),
(5299935, 770897, 53316, '<td valign="top">What amazingly gorgeous colors! And parts of this image look super-3D to me. Very awesome job.</td>', 'What amazingly gorgeous colors! And parts of this image look super-3D to me. Very awesome job.', '2009-03-10 22:08:56.000000', NULL, 1),
(5299936, 771651, 53316, '<td valign="top">This is indeed a beautiful image.</td>', 'This is indeed a beautiful image.', '2009-03-10 22:09:29.000000', NULL, 1),
(5300005, 771084, 90414, '<td valign="top">The threads in the fabric/carpet detracts from the coin but I like the reflection (as it looks like a mirror)and its'' bokeh.</td>', 'The threads in the fabric/carpet detracts from the coin but I like the reflection (as it looks like a mirror)and its'' bokeh.', '2009-03-10 22:52:32.000000', NULL, 1),
(5300406, 771229, 31772, '<td valign="top">I love these ground perspectives. Well done.</td>', 'I love these ground perspectives. Well done.', '2009-03-11 00:19:32.000000', NULL, 1),
(5300626, 771149, 53316, '<td valign="top">It''s quite a lovely image, but my eyes go a bit crazy looking at it. I think the big black stripes don''t help, because they just, to me, emphasize the "up and down a lot"-ness of the photo as being.. maybe out of place or wrong somehow? Instead of letting me view the "up and down" nature for what it is. I hope this makes sense!  Anyway, it''s a really great image - I absolutely love the colors, and the uniqueness of the trees.</td>', 'It''s quite a lovely image, but my eyes go a bit crazy looking at it. I think the big black stripes don''t help, because they just, to me, emphasize the "up and down a lot"-ness of the photo as being.. maybe out of place or wrong somehow? Instead of letting me view the "up and down" nature for what it is. I hope this makes sense!  Anyway, it''s a really great image - I absolutely love the colors, and the uniqueness of the trees.', '2009-03-11 00:35:15.000000', NULL, 1),
(5300858, 769987, 15511, '<td valign="top">It''s great to see an image that looks like real life; a good publish-quality photo. Well done, and thanks.</td>', 'It''s great to see an image that looks like real life; a good publish-quality photo. Well done, and thanks.', '2009-03-11 00:51:29.000000', NULL, 1),
(5303749, 771583, 97778, '<td valign="top">love the effect</td>', 'love the effect', '2009-03-11 06:29:53.000000', NULL, 1),
(5303773, 771645, 97778, '<td valign="top">excellent, love the mood and effect ...</td>', 'excellent, love the mood and effect ...', '2009-03-11 06:33:36.000000', NULL, 1),
(5303785, 771051, 97778, '<td valign="top">looks very authentic and wellvset up ... maybe a little less sharpness? just my preference ...</td>', 'looks very authentic and wellvset up ... maybe a little less sharpness? just my preference ...', '2009-03-11 06:35:00.000000', NULL, 1),
(5304869, 771030, 30049, '<td valign="top">I like the color tone choice.  Good time of day to capture this also - the lighting is just right.</td>', 'I like the color tone choice.  Good time of day to capture this also - the lighting is just right.', '2009-03-11 08:42:13.000000', NULL, 1),
(5305282, 771609, 73884, '<td valign="top">I like the tonality of this picture. It reminds me of a fairy tale. The harsh light from the window bothers me but otherwise is great. 8</td>', 'I like the tonality of this picture. It reminds me of a fairy tale. The harsh light from the window bothers me but otherwise is great. 8', '2009-03-11 09:10:45.000000', NULL, 1),
(5305307, 770649, 73884, '<td valign="top">I need to wake up early to take pictures like this... ;) 8</td>', 'I need to wake up early to take pictures like this... ;) 8', '2009-03-11 09:12:33.000000', NULL, 1),
(5305331, 770486, 73884, '<td valign="top">Nice take on a very popular landmark. 8</td>', 'Nice take on a very popular landmark. 8', '2009-03-11 09:14:19.000000', NULL, 1),
(5305344, 770897, 73884, '<td valign="top">It''s great how you captured both colors and shapes. Great job! 10</td>', 'It''s great how you captured both colors and shapes. Great job! 10', '2009-03-11 09:15:24.000000', NULL, 1),
(5305777, 771233, 76336, '<td valign="top">Wonderful study in color and reflections....you''d get my vote, if I could vote.</td>', 'Wonderful study in color and reflections....you''d get my vote, if I could vote.', '2009-03-11 09:47:20.000000', NULL, 1),
(5305813, 771616, 54228, '<td valign="top">Awesome DOF.</td>', 'Awesome DOF.', '2009-03-11 09:50:19.000000', NULL, 1),
(5306305, 771589, 60495, '<td valign="top">Great angle and the subdued lighting works nicely. I love the car so much I think I need to get busy and whittle myself one!</td>', 'Great angle and the subdued lighting works nicely. I love the car so much I think I need to get busy and whittle myself one!', '2009-03-11 10:19:01.000000', NULL, 1),
(5306400, 771323, 60495, '<td valign="top">I really like old buildings like this, and the editing works well giving the building an aged feel,  but The fish eye look to the shot makes the right side of the building lot awkward which to me kind of holds it back a little. Still overall a nice image.</td>', 'I really like old buildings like this, and the editing works well giving the building an aged feel,  but The fish eye look to the shot makes the right side of the building lot awkward which to me kind of holds it back a little. Still overall a nice image.', '2009-03-11 10:24:32.000000', NULL, 1),
(5306420, 771466, 60495, '<td valign="top">Looks like a great spot for a horror movie, I can almost see ghosts..... Very cool shot.</td>', 'Looks like a great spot for a horror movie, I can almost see ghosts..... Very cool shot.', '2009-03-11 10:25:50.000000', NULL, 1),
(5306505, 770869, 60495, '<td valign="top">Great DOF and the wide angle worked great, I especially like the Dentist sign in the window, it almost looks like the Dentist gets you in there and will not let you go. I bet there are some Dentist offices out there that would like a print of this one.</td>', 'Great DOF and the wide angle worked great, I especially like the Dentist sign in the window, it almost looks like the Dentist gets you in there and will not let you go. I bet there are some Dentist offices out there that would like a print of this one.', '2009-03-11 10:30:28.000000', NULL, 1),
(5306627, 770638, 60495, '<td valign="top">Very cool building, I love the old buildings they have so much character. I wish colors on this one did not look so unrealistic, I think they hold the image back. The reds and blues appear to be over saturated, the clock in the tower even has a blue cast and I assume the clock face likely should have been white.</td>', 'Very cool building, I love the old buildings they have so much character. I wish colors on this one did not look so unrealistic, I think they hold the image back. The reds and blues appear to be over saturated, the clock in the tower even has a blue cast and I assume the clock face likely should have been white.', '2009-03-11 10:38:58.000000', NULL, 1),
(5309662, 771294, 52549, '<td valign="top">Very good indeed. The perspective and the b/w are great.</td>', 'Very good indeed. The perspective and the b/w are great.', '2009-03-11 14:34:12.000000', NULL, 1),
(5309679, 770690, 101668, '<td valign="top">Wonderful picture.</td>', 'Wonderful picture.', '2009-03-11 14:35:38.000000', NULL, 1),
(5309696, 771163, 52549, '<td valign="top">Beautiful. My favourite so far.</td>', 'Beautiful. My favourite so far.', '2009-03-11 14:38:04.000000', NULL, 1),
