(5313675, 771557, 77724, '<td valign="top">Excellent light - I like how you get just a hint of the wood (guess) tone.</td>', 'Excellent light - I like how you get just a hint of the wood (guess) tone.', '2009-03-11 19:51:15.000000', NULL, 1),
(5313686, 771626, 61577, '<td valign="top">I have always liked this building, you captured it well in B &amp; W</td>', 'I have always liked this building, you captured it well in B & W', '2009-03-11 19:51:55.000000', NULL, 1),
(5313719, 771411, 77724, '<td valign="top">The smoke looks like it''s comming right out of the frame.  Nice B&amp;W treatment.</td>', 'The smoke looks like it''s comming right out of the frame.  Nice B&W treatment.', '2009-03-11 19:54:07.000000', NULL, 1),
