(5313753, 771536, 61577, '<td valign="top">Nice photo, I would like to see how it looks with a tighter crop</td>', 'Nice photo, I would like to see how it looks with a tighter crop', '2009-03-11 19:56:04.000000', NULL, 1),
(5313766, 771545, 61577, '<td valign="top">I like the soft foggy feel and the border works well</td>', 'I like the soft foggy feel and the border works well', '2009-03-11 19:56:52.000000', NULL, 1),
(5313778, 771616, 61577, '<td valign="top">Love the contrast between the foreground and the detail on the grave</td>', 'Love the contrast between the foreground and the detail on the grave', '2009-03-11 19:57:38.000000', NULL, 1),
(5313796, 771229, 61577, '<td valign="top">Nice POV and take on the contest</td>', 'Nice POV and take on the contest', '2009-03-11 19:58:39.000000', NULL, 1),
