(5314658, 771589, 90414, '<td valign="top">Very warm light and nicely composed - BUT, I believe this car was made in the early 1920''s...</td>', 'Very warm light and nicely composed - BUT, I believe this car was made in the early 1920''s...', '2009-03-11 20:59:27.000000', NULL, 1),
(5314698, 771474, 90414, '<td valign="top">This appears rather soft and tippy.</td>', 'This appears rather soft and tippy.', '2009-03-11 21:01:04.000000', NULL, 1),
(5314917, 771233, 90414, '<td valign="top">I''d like to see more of the ceiling, but the lighting from the stained glass is really beautiful and makes the shot. 7</td>', 'I''d like to see more of the ceiling, but the lighting from the stained glass is really beautiful and makes the shot. 7', '2009-03-11 21:11:35.000000', NULL, 1),
(5315861, 771323, 74534, '<td valign="top">Since you decided to use a wide angle, I wonder if it might have been better to take a couple of steps back and get more of the dramatic sky in.</td>', 'Since you decided to use a wide angle, I wonder if it might have been better to take a couple of steps back and get more of the dramatic sky in.', '2009-03-11 22:42:06.000000', NULL, 1),
(5315895, 771184, 74534, '<td valign="top">B&amp;W shots really suffer when the contrast is low. I would suggest making sure the dark end of your shot is anchored in pure black shadows, the highlights just barely touch pure white, and your subject is nicely lit. A great B&amp;W shot then has a rich range of tones in between, but that''s hard to achieve as it depends a lot on lighting and composition. Also, a completely blown sky that dominates the photo and leads the eye out will hurt.</td>', 'B&W shots really suffer when the contrast is low. I would suggest making sure the dark end of your shot is anchored in pure black shadows, the highlights just barely touch pure white, and your subject is nicely lit. A great B&W shot then has a rich range of tones in between, but that''s hard to achieve as it depends a lot on lighting and composition. Also, a completely blown sky that dominates the photo and leads the eye out will hurt.', '2009-03-11 22:45:18.000000', NULL, 1),
(5316186, 771182, 86090, '<td valign="top">This is great!!, I love the lighting, composition and colors.</td>', 'This is great!!, I love the lighting, composition and colors.', '2009-03-11 23:11:59.000000', NULL, 1),
(5316189, 771529, 74534, '<td valign="top">Excellent choice of a very original subject, what a breath of fresh air in an old challenge.</td>', 'Excellent choice of a very original subject, what a breath of fresh air in an old challenge.', '2009-03-11 23:12:27.000000', NULL, 1),
(5316193, 771628, 74534, '<td valign="top">Excellent B&amp;W treatment, it adds "punch", and I like the vignetting as well.</td>', 'Excellent B&W treatment, it adds "punch", and I like the vignetting as well.', '2009-03-11 23:12:38.000000', NULL, 1),
(5316195, 771296, 74534, '<td valign="top">This is a shot that will go unnoticed here, but would be right at home in a magazine, or on the wall of a nice restaurant somewhere. I like the grain / noise.</td>', 'This is a shot that will go unnoticed here, but would be right at home in a magazine, or on the wall of a nice restaurant somewhere. I like the grain / noise.', '2009-03-11 23:12:48.000000', NULL, 1),
