(5329569, 771523, 23317, '<td valign="top">I would have liked more focus.</td>', 'I would have liked more focus.', '2009-03-12 22:22:16.000000', NULL, 1),
(5329572, 771172, 23317, '<td valign="top">Nice lines and contrast.</td>', 'Nice lines and contrast.', '2009-03-12 22:22:35.000000', NULL, 1),
