(5329635, 771634, 23317, '<td valign="top">Nice originality</td>', 'Nice originality', '2009-03-12 22:28:37.000000', NULL, 1),
(5329641, 771131, 23317, '<td valign="top">Just couldn''t gain focus on a subject.</td>', 'Just couldn''t gain focus on a subject.', '2009-03-12 22:29:17.000000', NULL, 1),
(5329643, 771556, 74534, '<td valign="top">I am a huge fan of the aspect ratio that you get when using long focal lengths on landscapes like this. And in this particular image, it is not just aesthetically pleasing, but also powerful. The nature''s sheer force seems to overpower man''s structure, yet the cathedral has a power and majesty of its own. The black and white treatment lacks the usual contrast, but somehow contributes to give a timeless look to the image.<br/> <br/>Excellent shot. 10 from me and my personal blue ribbon in the challenge.</td>', 'I am a huge fan of the aspect ratio that you get when using long focal lengths on landscapes like this. And in this particular image, it is not just aesthetically pleasing, but also powerful. The nature''s sheer force seems to overpower man''s structure, yet the cathedral has a power and majesty of its own. The black and white treatment lacks the usual contrast, but somehow contributes to give a timeless look to the image. Excellent shot. 10 from me and my personal blue ribbon in the challenge.', '2009-03-12 22:29:20.000000', NULL, 1),
(5329659, 770779, 23317, '<td valign="top">The tourists take away the feel of 100 years old... even though the subject is 100 years old.</td>', 'The tourists take away the feel of 100 years old... even though the subject is 100 years old.', '2009-03-12 22:31:07.000000', NULL, 1),
(5329694, 771148, 23317, '<td valign="top">A longer exposure time may have brought a nice softness to the waterfall.  The perspective is very nice here, but the brightness of the reflections doesn''t allow my eyes to move a more comfortable point of focus.</td>', 'A longer exposure time may have brought a nice softness to the waterfall.  The perspective is very nice here, but the brightness of the reflections doesn''t allow my eyes to move a more comfortable point of focus.', '2009-03-12 22:33:53.000000', NULL, 1),
(5329709, 771572, 23317, '<td valign="top">More than what''s in my wallet at the moment.</td>', 'More than what''s in my wallet at the moment.', '2009-03-12 22:34:47.000000', NULL, 1),
