(5329895, 771596, 23317, '<td valign="top">Of the coins, these were my favorite, and there were A LOT of coins.</td>', 'Of the coins, these were my favorite, and there were A LOT of coins.', '2009-03-12 22:49:19.000000', NULL, 1),
(5329904, 771376, 23317, '<td valign="top">And I thought I hated ironing now.</td>', 'And I thought I hated ironing now.', '2009-03-12 22:49:52.000000', NULL, 1),
(5329911, 770642, 23317, '<td valign="top">Just wanted a little more focus.</td>', 'Just wanted a little more focus.', '2009-03-12 22:50:27.000000', NULL, 1),
(5329921, 770560, 16106, '<td valign="top">On the whole I like this image, but it seems to me that there is a bit much tree foliage and the trunk is a bit squeezed by the bottom of the frame. Had you either cropped it down off the top, or given more space to balance the composition, the lovely lines set up by the gravestones and the trees would have not caused the eye to slip off the page as easily. Other than that a nice composition and an elegant B&amp;W conversion.</td>', 'On the whole I like this image, but it seems to me that there is a bit much tree foliage and the trunk is a bit squeezed by the bottom of the frame. Had you either cropped it down off the top, or given more space to balance the composition, the lovely lines set up by the gravestones and the trees would have not caused the eye to slip off the page as easily. Other than that a nice composition and an elegant B&W conversion.', '2009-03-12 22:51:01.000000', NULL, 1),
(5329922, 771570, 23317, '<td valign="top">Sky and framing are nice.</td>', 'Sky and framing are nice.', '2009-03-12 22:51:01.000000', NULL, 1),
(5329929, 771030, 23317, '<td valign="top">Too many graves.</td>', 'Too many graves.', '2009-03-12 22:51:41.000000', NULL, 1),
(5329935, 771545, 23317, '<td valign="top">A litte too much softness / fog.</td>', 'A litte too much softness / fog.', '2009-03-12 22:52:10.000000', NULL, 1),
(5329941, 771300, 23317, '<td valign="top">I like the trees in the background and the softness of the water.</td>', 'I like the trees in the background and the softness of the water.', '2009-03-12 22:52:53.000000', NULL, 1),
(5329944, 771584, 60698, '<td valign="top">The lighting and feel of this is perfect! A fascinating old item with all those old birth records. Excellent!</td>', 'The lighting and feel of this is perfect! A fascinating old item with all those old birth records. Excellent!', '2009-03-12 22:53:04.000000', NULL, 1),
(5329945, 771109, 23317, '<td valign="top">Nice contrast with the sky.</td>', 'Nice contrast with the sky.', '2009-03-12 22:53:12.000000', NULL, 1),
