(5330096, 771202, 101668, '<td valign="top">Love the reflection on the floor. Beautiful picture. I don''t know much about photography technique but I "see" a good picture. This is a very good picture.</td>', 'Love the reflection on the floor. Beautiful picture. I don''t know much about photography technique but I "see" a good picture. This is a very good picture.', '2009-03-12 23:08:43.000000', NULL, 1),
(5330129, 771571, 101668, '<td valign="top">Of all the many churches entered in this challenge, this one is the very best.</td>', 'Of all the many churches entered in this challenge, this one is the very best.', '2009-03-12 23:12:58.000000', NULL, 1),
(5330182, 771459, 101668, '<td valign="top">Wonderful wonderful picture.</td>', 'Wonderful wonderful picture.', '2009-03-12 23:18:41.000000', NULL, 1),
