(5342765, 771131, 90414, '<td valign="top">This looks like Starve Rock in Wisconsin (am I close?) Great colors in the rock face, and good rule of thirds comp.</td>', 'This looks like Starve Rock in Wisconsin (am I close?) Great colors in the rock face, and good rule of thirds comp.', '2009-03-13 20:55:45.000000', NULL, 1),
(5342896, 770696, 90414, '<td valign="top">Very surreal image - I like the composition, but you''ve lost detail in the dress and the colors are a bit over-saturated imo.</td>', 'Very surreal image - I like the composition, but you''ve lost detail in the dress and the colors are a bit over-saturated imo.', '2009-03-13 21:10:21.000000', NULL, 1),
(5343136, 771227, 90414, '<td valign="top">Where''s the chainsaw when you need one? This would be a very nice shot, but the tree is really obtrusive imo... not that it was in your control, I know.</td>', 'Where''s the chainsaw when you need one? This would be a very nice shot, but the tree is really obtrusive imo... not that it was in your control, I know.', '2009-03-13 21:42:21.000000', NULL, 1),
