(5366168, 771529, 31664, '<td valign="top">Now we have undeniable proof!!  Aliens invented disco,  mirror ball and all.</td>', 'Now we have undeniable proof!!  Aliens invented disco,  mirror ball and all.', '2009-03-15 17:40:26.000000', NULL, 1),
(5366191, 771342, 31664, '<td valign="top">This is a beautifully presented shot, all the elements work together. Its so hard to make a stamp look interesting.  Love it. 10</td>', 'This is a beautifully presented shot, all the elements work together. Its so hard to make a stamp look interesting.  Love it. 10', '2009-03-15 17:42:31.000000', NULL, 1),
(5366276, 770608, 31664, '<td valign="top">I don''t feel the selective desat has worked for you here,  loosing the green in the grass but not in the cafe(?) area looks a little weird, and its also left some notable green fringing around the tree on the right.</td>', 'I don''t feel the selective desat has worked for you here,  loosing the green in the grass but not in the cafe(?) area looks a little weird, and its also left some notable green fringing around the tree on the right.', '2009-03-15 17:51:07.000000', NULL, 1),
(5366283, 770891, 31664, '<td valign="top">Love the looming clouds, shame about some of the haloing around the stones</td>', 'Love the looming clouds, shame about some of the haloing around the stones', '2009-03-15 17:51:58.000000', NULL, 1),
(5366356, 770992, 76335, '<td valign="top">Beautiful contrast.</td>', 'Beautiful contrast.', '2009-03-15 18:01:40.000000', NULL, 1),
(5366359, 771596, 76335, '<td valign="top">Nice textures, good dramatic lighting.</td>', 'Nice textures, good dramatic lighting.', '2009-03-15 18:01:52.000000', NULL, 1),
(5366368, 771457, 76335, '<td valign="top">Not sure about the mid-key processing A bit more contrast would have been nice. Still nicely composed.</td>', 'Not sure about the mid-key processing A bit more contrast would have been nice. Still nicely composed.', '2009-03-15 18:02:53.000000', NULL, 1),
(5366379, 771626, 76335, '<td valign="top">Fabulous angle. For all the modern marvels visible elsewhere, the building still stands as a reminder of a bygone era.</td>', 'Fabulous angle. For all the modern marvels visible elsewhere, the building still stands as a reminder of a bygone era.', '2009-03-15 18:04:09.000000', NULL, 1),
(5366389, 771392, 76335, '<td valign="top">Not sure I see the connection.</td>', 'Not sure I see the connection.', '2009-03-15 18:05:08.000000', NULL, 1),
(5366396, 771439, 76335, '<td valign="top">Nicely composed, good lighting.</td>', 'Nicely composed, good lighting.', '2009-03-15 18:05:40.000000', NULL, 1),
(5366404, 769987, 76335, '<td valign="top">Not sure the "ghost" was necessary, as the interior by itself makes a pretty strong statement. Still very good...</td>', 'Not sure the "ghost" was necessary, as the interior by itself makes a pretty strong statement. Still very good...', '2009-03-15 18:06:34.000000', NULL, 1),
(5366409, 771233, 76335, '<td valign="top">Stunning! Love the lighting and colors.</td>', 'Stunning! Love the lighting and colors.', '2009-03-15 18:06:47.000000', NULL, 1),
(5366428, 771254, 76335, '<td valign="top">Fabulous angle! Good subject isolation too. Don''t thinkg the border was needed though.</td>', 'Fabulous angle! Good subject isolation too. Don''t thinkg the border was needed though.', '2009-03-15 18:08:43.000000', NULL, 1),
(5366433, 771616, 76335, '<td valign="top">Nicely composed. Good in black and white</td>', 'Nicely composed. Good in black and white', '2009-03-15 18:09:07.000000', NULL, 1),
(5366435, 771408, 76335, '<td valign="top">Excellent textures here...</td>', 'Excellent textures here...', '2009-03-15 18:09:20.000000', NULL, 1),
(5366450, 770300, 76335, '<td valign="top">Lovely exposure.</td>', 'Lovely exposure.', '2009-03-15 18:09:55.000000', NULL, 1),
(5366454, 771589, 76335, '<td valign="top">Great idea for the challenge. Love the low angle and dramatic low-key lighting.</td>', 'Great idea for the challenge. Love the low angle and dramatic low-key lighting.', '2009-03-15 18:10:24.000000', NULL, 1),
(5366458, 770897, 76335, '<td valign="top">Stunning use of the frame to show off all those wonderful layers and shapes. I love the pastel colors...</td>', 'Stunning use of the frame to show off all those wonderful layers and shapes. I love the pastel colors...', '2009-03-15 18:11:20.000000', NULL, 1),
(5366460, 771628, 76335, '<td valign="top">I like the textures here...</td>', 'I like the textures here...', '2009-03-15 18:11:36.000000', NULL, 1),
(5366470, 771593, 76335, '<td valign="top">Great idea. Nice angle and colors.</td>', 'Great idea. Nice angle and colors.', '2009-03-15 18:12:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5366477, 771455, 76335, '<td valign="top">Fabulous although I''m sure your methods were called into question. Glad it wasn''t DQed.</td>', 'Fabulous although I''m sure your methods were called into question. Glad it wasn''t DQed.', '2009-03-15 18:13:03.000000', NULL, 1),
(5366487, 771547, 76335, '<td valign="top">Good set up, nice colors.</td>', 'Good set up, nice colors.', '2009-03-15 18:15:05.000000', NULL, 1),
(5366491, 771637, 76335, '<td valign="top">Stunning angle. The textures are beautifully shown.</td>', 'Stunning angle. The textures are beautifully shown.', '2009-03-15 18:16:15.000000', NULL, 1),
(5366492, 771245, 76335, '<td valign="top">A bit oversaturated...</td>', 'A bit oversaturated...', '2009-03-15 18:16:30.000000', NULL, 1),
(5366494, 771249, 76335, '<td valign="top">And shown to maximum baroque effect. Very ornate. Nice job.</td>', 'And shown to maximum baroque effect. Very ornate. Nice job.', '2009-03-15 18:17:24.000000', NULL, 1),
(5366495, 771627, 76335, '<td valign="top">Beautiful use of sepia.</td>', 'Beautiful use of sepia.', '2009-03-15 18:17:34.000000', NULL, 1),
(5366502, 771466, 76335, '<td valign="top">Creepy green... I like it.</td>', 'Creepy green... I like it.', '2009-03-15 18:18:18.000000', NULL, 1),
(5366513, 771602, 76335, '<td valign="top">I like the low angle. Nice sky too.</td>', 'I like the low angle. Nice sky too.', '2009-03-15 18:19:17.000000', NULL, 1),
(5366518, 771609, 76335, '<td valign="top">Good use of natural light to show this off.</td>', 'Good use of natural light to show this off.', '2009-03-15 18:19:47.000000', NULL, 1),
(5366524, 771342, 76335, '<td valign="top">Great title. Nicely composed and executed. The details are crisp.</td>', 'Great title. Nicely composed and executed. The details are crisp.', '2009-03-15 18:20:24.000000', NULL, 1),
(5366525, 771296, 76335, '<td valign="top">I like the film-like grain.</td>', 'I like the film-like grain.', '2009-03-15 18:20:39.000000', NULL, 1),
(5366528, 770556, 76335, '<td valign="top">Lensbaby? Nice job.</td>', 'Lensbaby? Nice job.', '2009-03-15 18:20:50.000000', NULL, 1),
(5366534, 771300, 76335, '<td valign="top">I love the colors here.</td>', 'I love the colors here.', '2009-03-15 18:21:04.000000', NULL, 1),
(5366536, 771625, 76335, '<td valign="top">The lighting is beautiful.</td>', 'The lighting is beautiful.', '2009-03-15 18:21:39.000000', NULL, 1),
(5366869, 771351, 76335, '<td valign="top">Nice lighting, beautifully shown off.</td>', 'Nice lighting, beautifully shown off.', '2009-03-15 18:50:00.000000', NULL, 1),
