(5366896, 771030, 76335, '<td valign="top">Nice duotone.</td>', 'Nice duotone.', '2009-03-15 18:52:27.000000', NULL, 1),
(5366916, 770911, 76335, '<td valign="top">Beautiffully exposed and presented.</td>', 'Beautiffully exposed and presented.', '2009-03-15 18:54:19.000000', NULL, 1),
