(5366947, 771545, 76335, '<td valign="top">Pinhole? Nice processing but I''m not convinced these are 100 year old oaks.</td>', 'Pinhole? Nice processing but I''m not convinced these are 100 year old oaks.', '2009-03-15 18:58:42.000000', NULL, 1),
(5366952, 771257, 76335, '<td valign="top">That''s a stretch.</td>', 'That''s a stretch.', '2009-03-15 18:59:02.000000', NULL, 1),
